mapper.select:
select s.id, s.name, s.no, s.gender, s.phone, s.degree, s.id_card as idCard, s.is_college as isCollege, s.address, s.graduation_date as graduationDate, s.violation_count as violationCount, s.violation_score as violationScore, s.clazz_id as clazzId, s.create_time as createTime, s.update_time as updateTime, c.name as clazzName from student as s left join clazz as c on s.clazz_id = c.id
s.name like concat('%',#{name},'%')
and s.degree = #{degree}
and s.clazz_id = #{clazzId}
order by s.create_time desc
